//! Envelope sweep: every pulse a visitor can program from the planner with one
//! control moved at a time, run through the engine exactly as the control
//! room runs it, with the outputs checked for plausibility rather than for
//! particular numbers.
//!
//! The programs come from `tests/fixtures/program_matrix.json`, generated by
//! the frontend's own program builder (`web/src/lib/programMatrix.ts`,
//! `npm run matrix:emit`), so the sweep covers the programs the planner can
//! actually make and nothing else.
//!
//! Tiers:
//!   1. hard invariants at every step and at the end of every pulse (finite,
//!      signed, bounded, latched, terminating);
//!   3. sweep-level checks that need no absolute numbers: a slider must move
//!      something, and a few directions that follow from the models;
//!   4. a golden summary of the twelve default presets, with a 1 % band.
//! (Tier 2, model-envelope bounds, is written once the first sweep has been
//! read; see the module notes at the bottom.)
//!
//! Run with:
//!   cargo test --release -p tok-sym-core --test envelope -- --nocapture
//!   UPDATE_GOLDEN=1 cargo test --release -p tok-sym-core --test envelope
//!   ENVELOPE_ONLY=diiid/hmode cargo test ... (prefix filter on entry ids)
//!   ENVELOPE_THREADS=4 cargo test ...        (default: min(6, cores))

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;
use std::sync::Mutex;
use std::time::Instant;
use tok_sym_core::devices;
use tok_sym_core::simulation::{PulseProgram, Simulation, SimulationSnapshot, SimulationStatus};

/// The control room's physics step and its fine step inside a quench
/// (`web/src/lib/useSimulation.ts`).
const DT: f64 = 0.005;
const DT_QUENCH: f64 = 0.00025;
/// Relative band on the continuous golden metrics; discrete ones are exact.
const GOLDEN_REL_TOL: f64 = 0.01;
const GOLDEN_ABS_FLOOR: f64 = 1e-3;

#[derive(Deserialize)]
struct Entry {
    id: String,
    device: String,
    preset: String,
    knob: String,
    level: u32,
    value: serde_json::Value,
    mass_number: Option<f64>,
    program: PulseProgram,
}

/// Per-pulse summary. Everything a sweep-level check or the golden file
/// needs, computed online so no snapshot history is kept.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct Summary {
    id: String,
    steps: usize,
    t_end: f64,
    status: String,
    disrupted: bool,
    disruption_time: f64,
    cause: String,
    quench_duration: f64,
    peak_w_th: f64,
    peak_beta_n: f64,
    max_fgw: f64,
    min_q95: f64,
    max_zeff: f64,
    peak_p_rad: f64,
    peak_te0: f64,
    peak_p_alpha: f64,
    time_in_hmode: f64,
    elm_count: u32,
    flux_fraction_end: f64,
    flux_exhausted: bool,
    saturated_time: f64,
    flat_top_v_mean: f64,
    max_abs_v: f64,
    max_tracking_error: f64,
    /// (kind, message) pairs; the kind is what the known-issue register matches.
    #[serde(skip)]
    violations: Vec<(String, String)>,
}

struct Tally {
    sum_v: f64,
    t_v: f64,
    prev: Option<SimulationSnapshot>,
    elm_was_active: bool,
    quench_start: Option<f64>,
    ip_scale: f64,
    /// First occurrence, count and last time of each violation kind, so a
    /// rule firing on every step produces one line, not thousands.
    seen: BTreeMap<String, Seen>,
}

struct Seen {
    count: usize,
    first: String,
    last_t: f64,
}

fn violate(tally: &mut Tally, out: &mut Summary, kind: &str, t: f64, detail: String) {
    let _ = &out;
    let e = tally.seen.entry(kind.to_string()).or_insert_with(|| Seen { count: 0, first: format!("t={t:.3}s {kind}: {detail}"), last_t: t });
    e.count += 1;
    e.last_t = t;
}

fn finite_fields(s: &SimulationSnapshot) -> Vec<(&'static str, f64)> {
    let d = &s.diagnostics;
    vec![
        ("ip", s.ip), ("bt", s.bt), ("te0", s.te0), ("ne_bar", s.ne_bar), ("w_th", s.w_th),
        ("tau_e", s.tau_e), ("p_input", s.p_input), ("p_ohmic", s.p_ohmic), ("p_rad", s.p_rad),
        ("p_loss", s.p_loss), ("p_alpha", s.p_alpha), ("beta_n", s.beta_n), ("beta_t", s.beta_t),
        ("q95", s.q95), ("f_greenwald", s.f_greenwald), ("li", s.li), ("h_factor", s.h_factor),
        ("elm_energy_loss", s.elm_energy_loss), ("ne_ped", s.ne_ped), ("te_ped", s.te_ped),
        ("ne_line", s.ne_line), ("impurity_fraction", s.impurity_fraction), ("imp_n", s.imp_n),
        ("imp_ne", s.imp_ne), ("imp_ar", s.imp_ar), ("z_eff", s.z_eff), ("fuel_fraction", s.fuel_fraction),
        ("disruption_risk", s.disruption_risk), ("risk_greenwald", s.risk_greenwald),
        ("risk_beta", s.risk_beta), ("risk_q95", s.risk_q95), ("risk_radiation", s.risk_radiation),
        ("risk_locked_mode", s.risk_locked_mode), ("p_lh", s.p_lh), ("v_loop", s.v_loop),
        ("flux_consumed", s.flux_consumed), ("flux_budget", s.flux_budget),
        ("i_bootstrap", s.i_bootstrap), ("i_cd", s.i_cd), ("axis_r", s.axis_r), ("axis_z", s.axis_z),
        ("xpoint_r", s.xpoint_r), ("xpoint_z", s.xpoint_z), ("xpoint_upper_r", s.xpoint_upper_r),
        ("xpoint_upper_z", s.xpoint_upper_z), ("prog_ip", s.prog_ip), ("prog_ne", s.prog_ne),
        ("diag.ip", d.ip), ("diag.ne_bar", d.ne_bar), ("diag.te0", d.te0), ("diag.w_mhd", d.w_mhd),
        ("diag.p_rad", d.p_rad), ("diag.d_alpha", d.d_alpha), ("diag.soft_xray", d.soft_xray),
        ("diag.locked_mode", d.locked_mode), ("diag.neutron_rate", d.neutron_rate),
        ("diag.p_input", d.p_input), ("diag.beta_n", d.beta_n), ("diag.q95", d.q95),
        ("diag.f_greenwald", d.f_greenwald), ("diag.v_loop", d.v_loop),
    ]
}

/// Tier 1, per step.
fn check_step(e: &Entry, dev: &devices::Device, s: &SimulationSnapshot, tally: &mut Tally, out: &mut Summary) {
    let t = s.time;
    for (name, v) in finite_fields(s) {
        if !v.is_finite() {
            violate(tally, out, "non-finite", t, format!("{name} = {v}"));
        }
    }
    if s.te_profile.iter().chain(s.ne_profile.iter()).any(|v| !v.is_finite() || *v < 0.0) {
        violate(tally, out, "profile", t, "negative or non-finite point in te/ne profile".into());
    }
    if s.separatrix.points.iter().any(|(r, z)| !r.is_finite() || !z.is_finite()) {
        violate(tally, out, "separatrix", t, "non-finite separatrix point".into());
    }
    for (name, v) in [
        ("ip", s.ip), ("bt", s.bt), ("te0", s.te0), ("ne_bar", s.ne_bar), ("w_th", s.w_th),
        ("tau_e", s.tau_e), ("p_input", s.p_input), ("p_ohmic", s.p_ohmic), ("p_rad", s.p_rad),
        ("p_loss", s.p_loss), ("p_alpha", s.p_alpha), ("beta_n", s.beta_n), ("beta_t", s.beta_t),
        ("f_greenwald", s.f_greenwald), ("h_factor", s.h_factor), ("ne_ped", s.ne_ped),
        ("te_ped", s.te_ped), ("ne_line", s.ne_line), ("p_lh", s.p_lh), ("i_bootstrap", s.i_bootstrap),
        ("i_cd", s.i_cd), ("elm_energy_loss", s.elm_energy_loss), ("prog_ip", s.prog_ip),
    ] {
        if v < -1e-9 {
            violate(tally, out, "negative", t, format!("{name} = {v:.4e}"));
        }
    }
    for (name, v) in [
        ("impurity_fraction", s.impurity_fraction), ("imp_n", s.imp_n), ("imp_ne", s.imp_ne),
        ("imp_ar", s.imp_ar), ("fuel_fraction", s.fuel_fraction), ("disruption_risk", s.disruption_risk),
        ("risk_greenwald", s.risk_greenwald), ("risk_beta", s.risk_beta), ("risk_q95", s.risk_q95),
        ("risk_radiation", s.risk_radiation), ("risk_locked_mode", s.risk_locked_mode),
    ] {
        if !(-1e-9..=1.0 + 1e-9).contains(&v) {
            violate(tally, out, "fraction out of [0,1]", t, format!("{name} = {v:.4}"));
        }
    }
    if s.z_eff < 1.0 - 1e-9 {
        violate(tally, out, "z_eff below 1", t, format!("z_eff = {:.4}", s.z_eff));
    }
    // The pedestal is an H-mode feature; the L-mode "pedestal" numbers are
    // profile shape parameters with floors that sit above a cold start-up
    // core (reported separately, see the notes at the bottom). A collapsing
    // core during a disruption precursor is not a pedestal fault either.
    let established = s.ip >= 0.1 * tally.ip_scale && s.in_hmode && !s.disrupted;
    if established && s.te_ped > s.te0 * (1.0 + 1e-6) + 1e-9 {
        violate(tally, out, "pedestal above core", t, format!("te_ped {:.3} > te0 {:.3} keV", s.te_ped, s.te0));
    }
    if let Some(ne0) = s.ne_profile.first() {
        if established && s.ne_ped > ne0 * (1.0 + 1e-6) + 1e-9 {
            violate(tally, out, "density pedestal above core", t, format!("ne_ped {:.3} > ne0 {:.3}", s.ne_ped, ne0));
        }
    }
    if s.ip > 0.01 && s.q95 <= 0.0 {
        violate(tally, out, "q95 not positive", t, format!("q95 = {:.3} at Ip {:.3} MA", s.q95, s.ip));
    }
    if !(0.0..=5.0).contains(&s.li) {
        violate(tally, out, "li out of (0,5)", t, format!("li = {:.3}", s.li));
    }
    if !s.disrupted && !s.flux_exhausted && s.v_loop.abs() > dev.v_loop_max * (1.0 + 1e-6) {
        violate(tally, out, "loop voltage beyond supply", t, format!("|V| = {:.3} > {:.1} V", s.v_loop.abs(), dev.v_loop_max));
    }
    if s.flux_consumed > s.flux_budget + 1e-6 {
        violate(tally, out, "flux beyond budget", t, format!("{:.3} > {:.3} V·s", s.flux_consumed, s.flux_budget));
    }
    if s.flux_budget <= 0.0 {
        violate(tally, out, "flux budget not positive", t, format!("{}", s.flux_budget));
    }
    let (r0, a) = (dev.r0, dev.a);
    if s.ip > 0.05 * tally.ip_scale && ((s.axis_r - r0).abs() > a || s.axis_z.abs() > dev.kappa * a) {
        violate(tally, out, "magnetic axis outside the plasma", t, format!("axis ({:.3}, {:.3}) for R0={r0:.2} a={a:.2}", s.axis_r, s.axis_z));
    }
    // A diverted plasma carrying current must have a traced separatrix; a
    // limited one has none, and a quenching one may lose it as Ip collapses.
    if !s.is_limited && !s.disrupted && s.ip >= 0.1 * tally.ip_scale && s.separatrix.points.len() < 8 {
        violate(tally, out, "separatrix missing", t, format!("{} points at Ip {:.3} MA", s.separatrix.points.len(), s.ip));
    }
    if !["", "precursor", "thermal_quench", "current_quench", "complete"].contains(&s.disruption_phase.as_str()) {
        violate(tally, out, "unknown disruption phase", t, s.disruption_phase.clone());
    }
    let prev = tally.prev.as_ref().map(|p| (p.time, p.disrupted, p.flux_exhausted, p.status, p.prog_ip));
    if let Some((p_time, p_disrupted, p_exhausted, p_status, p_prog_ip)) = prev {
        if s.time <= p_time {
            violate(tally, out, "time not advancing", t, format!("{} after {}", s.time, p_time));
        }
        if p_disrupted && !s.disrupted {
            violate(tally, out, "disruption un-latched", t, "disrupted went true -> false".into());
        }
        // The hold may release when the program ramps down, or when flux
        // comes back to the solenoid (an inductance drop hands back I·ΔL):
        // either way the loop voltage on the releasing step is not positive.
        // Releasing with the supply pushing is the re-arm the latch exists
        // to prevent.
        if p_exhausted && !s.flux_exhausted && s.prog_ip >= p_prog_ip - 1e-12 && s.v_loop > 1e-9 {
            violate(tally, out, "flux exhaustion re-armed", t, format!("flux_exhausted cleared with V = {:.3} V while the program holds Ip at {:.3} MA", s.v_loop, s.prog_ip));
        }
        if p_status != SimulationStatus::Running && s.status != p_status {
            violate(tally, out, "status moved after the end", t, format!("{:?} -> {:?}", p_status, s.status));
        }
    }
    let _ = e;
}

fn run_entry(e: &Entry) -> Summary {
    let dev = devices::get_device(&e.device).unwrap_or_else(|| panic!("unknown device {}", e.device));
    let mut sim = Simulation::new(dev.clone(), e.program.clone());
    if let Some(m) = e.mass_number {
        sim.device.mass_number = m;
    }
    sim.start();
    let mut out = Summary { id: e.id.clone(), min_q95: f64::INFINITY, ..Default::default() };
    let ip_scale = e.program.ip.iter().map(|p| p.1).fold(0.0, f64::max).max(0.05);
    let mut tally = Tally { sum_v: 0.0, t_v: 0.0, prev: None, elm_was_active: false, quench_start: None, ip_scale, seen: BTreeMap::new() };
    // Termination guard: the fine quench step over the whole pulse, plus slack.
    let max_steps = (e.program.duration / DT_QUENCH) as usize + 1000;
    loop {
        let in_quench = tally.prev.as_ref().map_or(false, |p| {
            p.disrupted && (p.disruption_phase == "thermal_quench" || p.disruption_phase == "current_quench")
        });
        let dt = if in_quench { DT_QUENCH } else { DT };
        let s = sim.step(dt);
        out.steps += 1;
        check_step(e, &dev, &s, &mut tally, &mut out);

        // ── summary metrics ──
        if !s.disrupted {
            out.peak_w_th = out.peak_w_th.max(s.w_th);
            out.peak_p_rad = out.peak_p_rad.max(s.p_rad);
            out.peak_te0 = out.peak_te0.max(s.te0);
            out.peak_p_alpha = out.peak_p_alpha.max(s.p_alpha);
            out.max_abs_v = out.max_abs_v.max(s.v_loop.abs());
            if s.ip > 0.1 * ip_scale {
                // Start-up floors (density, pedestal targets) dominate these
                // ratios while the current is tiny; they mean nothing there.
                out.min_q95 = out.min_q95.min(s.q95);
                out.max_fgw = out.max_fgw.max(s.f_greenwald);
                out.peak_beta_n = out.peak_beta_n.max(s.beta_n);
                out.max_zeff = out.max_zeff.max(s.z_eff);
            }
            if s.in_hmode {
                out.time_in_hmode += dt;
            }
            if s.elm_active && !tally.elm_was_active {
                out.elm_count += 1;
            }
            tally.elm_was_active = s.elm_active;
            if s.oh_saturated {
                out.saturated_time += dt;
            }
            if s.prog_ip >= 0.95 * s.prog_ip_peak && s.prog_ip_peak > 0.0 {
                tally.sum_v += s.v_loop * dt;
                tally.t_v += dt;
                let err = (s.ip - s.prog_ip).abs() / s.prog_ip_peak;
                out.max_tracking_error = out.max_tracking_error.max(err);
            }
            out.flux_fraction_end = if s.flux_budget > 0.0 { s.flux_consumed / s.flux_budget } else { 0.0 };
            out.flux_exhausted = s.flux_exhausted;
        } else if out.disruption_time == 0.0 {
            out.disruption_time = s.time;
        }
        if s.disrupted && tally.quench_start.is_none() && s.disruption_phase == "thermal_quench" {
            tally.quench_start = Some(s.time);
        }
        let done = s.status != SimulationStatus::Running;
        out.t_end = s.time;
        out.status = format!("{:?}", s.status);
        out.disrupted = s.disrupted;
        out.cause = s.disruption_cause.clone();
        if let Some(q0) = tally.quench_start {
            out.quench_duration = s.time - q0;
        }
        tally.prev = Some(s);
        if done {
            break;
        }
        if out.steps >= max_steps {
            out.violations.push(("hang".into(), format!("t={:.3}s still Running after {} steps", out.t_end, out.steps)));
            break;
        }
    }
    if tally.t_v > 0.0 {
        out.flat_top_v_mean = tally.sum_v / tally.t_v;
    }
    for (kind, seen) in &tally.seen {
        out.violations.push((kind.clone(), format!("{} [{} steps, last t={:.3}s]", seen.first, seen.count, seen.last_t)));
    }
    if !out.min_q95.is_finite() {
        out.min_q95 = 0.0;
    }

    // ── Tier 1, per pulse ──
    if out.status == "Complete" && (out.t_end - e.program.duration).abs() > DT + 1e-9 {
        out.violations.push(("ended early".into(), format!("ended Complete at t={:.3}s, duration {:.3}s", out.t_end, e.program.duration)));
    }
    if out.disrupted && out.cause.is_empty() {
        out.violations.push(("no cause".into(), "disrupted without a recorded cause".into()));
    }
    if out.status == "Disrupted" && tally.prev.as_ref().map_or(false, |p| p.ip >= 0.01) {
        out.violations.push(("unquenched".into(), "status Disrupted while Ip has not quenched".into()));
    }
    if e.knob == "base" && e.preset != "density_limit" && out.disrupted {
        out.violations.push(("default preset disrupts".into(), format!("default {} preset disrupts at t={:.2}s ({})", e.preset, out.disruption_time, out.cause)));
    }
    out
}

/// Engine findings the sweep reproduces today. Each is (entry id, violation
/// kind, note). A listed finding is reported as known instead of failing the
/// suite; one that stops reproducing fails the suite until its line is
/// removed, so the register cannot go stale. Fixing the engine is the way
/// to shorten this list; adding to it is a flagged decision.
const KNOWN_ISSUES: &[(&str, &str, &str)] = &[];

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name)
}

fn load_matrix() -> Vec<Entry> {
    let path = fixture("program_matrix.json");
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}; run `npm run matrix:emit` in web/", path.display()));
    let mut entries: Vec<Entry> = serde_json::from_str(&text).expect("program_matrix.json parses");
    if let Ok(only) = std::env::var("ENVELOPE_ONLY") {
        entries.retain(|e| e.id.starts_with(&only));
    }
    entries
}

fn run_all(entries: &[Entry]) -> Vec<Summary> {
    let threads = std::env::var("ENVELOPE_THREADS").ok().and_then(|v| v.parse().ok()).unwrap_or_else(|| {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1).min(6)
    });
    let next = Mutex::new(0usize);
    let results: Mutex<Vec<Option<Summary>>> = Mutex::new(vec![None; entries.len()]);
    std::thread::scope(|scope| {
        for _ in 0..threads {
            scope.spawn(|| loop {
                let i = {
                    let mut n = next.lock().unwrap();
                    let i = *n;
                    *n += 1;
                    i
                };
                if i >= entries.len() {
                    break;
                }
                let s = run_entry(&entries[i]);
                results.lock().unwrap()[i] = Some(s);
            });
        }
    });
    results.into_inner().unwrap().into_iter().map(|s| s.expect("every entry ran")).collect()
}

fn fmt_value(v: &serde_json::Value) -> String {
    match v {
        serde_json::Value::Null => "-".into(),
        serde_json::Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

fn print_table(entries: &[Entry], results: &[Summary]) {
    println!("{:<34} {:>9} {:>6} {:>7} {:>7} {:>6} {:>6} {:>6} {:>6} {:>6} {:>6} {:>6} {:>6} {:>5}  {}",
        "id", "value", "t_end", "W_pk", "βN_pk", "fGWmx", "q95mn", "Zeffmx", "Prad", "tH", "ELMs", "ΨOH", "Vflat", "trk%", "outcome");
    for (e, s) in entries.iter().zip(results) {
        let outcome = if s.disrupted { format!("DISRUPT {:.2}s {}", s.disruption_time, s.cause) } else { s.status.clone() };
        println!("{:<34} {:>9} {:>6.2} {:>7.3} {:>7.3} {:>6.2} {:>6.2} {:>6.2} {:>6.2} {:>6.2} {:>6} {:>6.2} {:>6.2} {:>5.1}  {}",
            e.id, fmt_value(&e.value), s.t_end, s.peak_w_th, s.peak_beta_n, s.max_fgw, s.min_q95, s.max_zeff,
            s.peak_p_rad, s.time_in_hmode, s.elm_count, s.flux_fraction_end, s.flat_top_v_mean,
            s.max_tracking_error * 100.0, outcome);
    }
}

/// Tier 3: a slider must move at least one summary metric across its range,
/// and a few directions that follow from the models hold between its lowest
/// and highest level whenever neither pulse disrupted.
fn sweep_checks(entries: &[Entry], results: &[Summary]) -> Vec<String> {
    let mut groups: BTreeMap<(String, String, String), Vec<(u32, &Summary)>> = BTreeMap::new();
    for (e, s) in entries.iter().zip(results) {
        if matches!(e.knob.as_str(), "base" | "fuel" | "config") {
            continue;
        }
        groups.entry((e.device.clone(), e.preset.clone(), e.knob.clone())).or_default().push((e.level, s));
    }
    let mut failures = Vec::new();
    let sig = |s: &Summary| {
        format!("{:.6e} {:.6e} {:.6e} {:.6e} {:.6e} {:.3} {:.6e} {:.3} {}",
            s.peak_w_th, s.max_fgw, s.min_q95, s.max_zeff, s.peak_p_rad, s.disruption_time, s.flux_fraction_end, s.time_in_hmode, s.elm_count)
    };
    for ((dev, preset, knob), mut levels) in groups {
        levels.sort_by_key(|(l, _)| *l);
        if levels.len() < 2 {
            continue;
        }
        let sigs: Vec<String> = levels.iter().map(|(_, s)| sig(s)).collect();
        if sigs.iter().all(|x| *x == sigs[0]) {
            failures.push(format!("{dev}/{preset}/{knob}: dead control — every level gives the same outcome"));
        }
        let lo = levels.first().unwrap().1;
        let hi = levels.last().unwrap().1;
        if lo.disrupted || hi.disrupted {
            continue;
        }
        let tag = format!("{dev}/{preset}/{knob} (lowest vs highest level)");
        let slack = 1.0 - 0.02;
        match knob.as_str() {
            "p_nbi" | "p_ech" => {
                if hi.peak_w_th < lo.peak_w_th * slack {
                    failures.push(format!("{tag}: more heating lowered peak W_th {:.3} -> {:.3} MJ", lo.peak_w_th, hi.peak_w_th));
                }
            }
            "ne" => {
                if hi.max_fgw < lo.max_fgw * slack {
                    failures.push(format!("{tag}: higher density target lowered max fGW {:.3} -> {:.3}", lo.max_fgw, hi.max_fgw));
                }
            }
            "ip" => {
                if hi.min_q95 > lo.min_q95 / slack {
                    failures.push(format!("{tag}: more current raised min q95 {:.3} -> {:.3}", lo.min_q95, hi.min_q95));
                }
            }
            "n2_puff" | "neon_puff" | "argon_puff" => {
                if hi.max_zeff < lo.max_zeff * slack {
                    failures.push(format!("{tag}: more seeding lowered max Z_eff {:.3} -> {:.3}", lo.max_zeff, hi.max_zeff));
                }
                if hi.peak_p_rad < lo.peak_p_rad * slack {
                    failures.push(format!("{tag}: more seeding lowered peak P_rad {:.3} -> {:.3} MW", lo.peak_p_rad, hi.peak_p_rad));
                }
            }
            _ => {}
        }
    }
    failures
}

/// Tier 4: the twelve default presets against the committed golden summary.
fn golden_checks(entries: &[Entry], results: &[Summary]) -> Vec<String> {
    let path = fixture("envelope_golden.json");
    let current: BTreeMap<String, Summary> = entries.iter().zip(results)
        .filter(|(e, _)| e.knob == "base")
        .map(|(e, s)| (e.id.clone(), s.clone()))
        .collect();
    let update = std::env::var("UPDATE_GOLDEN").map_or(false, |v| v == "1");
    if update || !path.exists() {
        fs::write(&path, serde_json::to_string_pretty(&current).unwrap()).unwrap();
        println!("wrote golden summary for {} presets to {}", current.len(), path.display());
        return if update { vec![] } else { vec![format!("golden file was missing and has been written to {}; rerun", path.display())] };
    }
    let golden: BTreeMap<String, Summary> = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
    let mut failures = Vec::new();
    let near = |a: f64, b: f64| (a - b).abs() <= GOLDEN_REL_TOL * b.abs().max(GOLDEN_ABS_FLOOR);
    for (id, now) in &current {
        let Some(g) = golden.get(id) else {
            failures.push(format!("{id}: no golden entry (UPDATE_GOLDEN=1 to add)"));
            continue;
        };
        let mut diffs = Vec::new();
        for (name, a, b) in [
            ("peak_w_th", now.peak_w_th, g.peak_w_th), ("peak_beta_n", now.peak_beta_n, g.peak_beta_n),
            ("max_fgw", now.max_fgw, g.max_fgw), ("min_q95", now.min_q95, g.min_q95),
            ("max_zeff", now.max_zeff, g.max_zeff), ("peak_p_rad", now.peak_p_rad, g.peak_p_rad),
            ("peak_te0", now.peak_te0, g.peak_te0), ("peak_p_alpha", now.peak_p_alpha, g.peak_p_alpha),
            ("time_in_hmode", now.time_in_hmode, g.time_in_hmode), ("flux_fraction_end", now.flux_fraction_end, g.flux_fraction_end),
            ("flat_top_v_mean", now.flat_top_v_mean, g.flat_top_v_mean), ("t_end", now.t_end, g.t_end),
            ("disruption_time", now.disruption_time, g.disruption_time), ("quench_duration", now.quench_duration, g.quench_duration),
        ] {
            if !near(a, b) {
                diffs.push(format!("{name} {b:.4} -> {a:.4}"));
            }
        }
        if now.disrupted != g.disrupted || now.cause != g.cause || now.status != g.status {
            diffs.push(format!("outcome {}/{}/{} -> {}/{}/{}", g.status, g.disrupted, g.cause, now.status, now.disrupted, now.cause));
        }
        if now.flux_exhausted != g.flux_exhausted {
            diffs.push(format!("flux_exhausted {} -> {}", g.flux_exhausted, now.flux_exhausted));
        }
        if (now.elm_count as i64 - g.elm_count as i64).abs() > (g.elm_count as f64 * 0.05).ceil() as i64 {
            diffs.push(format!("elm_count {} -> {}", g.elm_count, now.elm_count));
        }
        if !diffs.is_empty() {
            failures.push(format!("{id}: {}", diffs.join(", ")));
        }
    }
    failures
}

#[test]
fn envelope_sweep() {
    let entries = load_matrix();
    assert!(!entries.is_empty(), "no matrix entries selected");
    let t0 = Instant::now();
    let results = run_all(&entries);
    let steps: usize = results.iter().map(|s| s.steps).sum();
    print_table(&entries, &results);
    println!("\n{} pulses, {} steps, {:.1} s wall", entries.len(), steps, t0.elapsed().as_secs_f64());

    let mut failures: Vec<String> = Vec::new();
    let mut known: Vec<String> = Vec::new();
    let mut reproduced: Vec<bool> = vec![false; KNOWN_ISSUES.len()];
    for (e, s) in entries.iter().zip(&results) {
        for (kind, v) in &s.violations {
            let line = format!("{} ({}={}): {v}", e.id, e.knob, fmt_value(&e.value));
            if let Some(idx) = KNOWN_ISSUES.iter().position(|(i, k, _)| *i == e.id && *k == kind) {
                reproduced[idx] = true;
                known.push(format!("{line}\n      known: {}", KNOWN_ISSUES[idx].2));
            } else {
                failures.push(format!("[tier 1] {line}"));
            }
        }
    }
    let filtered = std::env::var("ENVELOPE_ONLY").is_ok();
    if !known.is_empty() {
        println!("\n{} known engine findings reproduced:", known.len());
        for k in &known {
            println!("  {k}");
        }
    }
    for (i, (id, kind, _)) in KNOWN_ISSUES.iter().enumerate() {
        let selected = entries.iter().any(|e| e.id == *id);
        if selected && !reproduced[i] {
            failures.push(format!("[register] known issue no longer reproduces, remove it: {id} / {kind}"));
        }
    }
    if !filtered {
        failures.extend(sweep_checks(&entries, &results).into_iter().map(|f| format!("[tier 3] {f}")));
        failures.extend(golden_checks(&entries, &results).into_iter().map(|f| format!("[tier 4] {f}")));
    }
    if !failures.is_empty() {
        println!("\n{} failures:", failures.len());
        for f in &failures {
            println!("  {f}");
        }
    }
    assert!(failures.is_empty(), "{} envelope failures (see list above)", failures.len());
}

// First-sweep findings, all fixed on this branch: the δ slider maximum
// overflowed asin through DIII-D's fitted δ offset (now a device-aware
// range plus DELTA_EQ_MAX in the engine); upper single null anchored its
// separatrix on the lower-δ X-point position and lost the boundary; the Ip
// slider minimum sat on the engine's 0.1 MA display threshold (now a
// tenth of the rating); and the flux hold skipped its budget clip on the
// releasing step and misreported the pinned flux by L_v ΔI.
